pub(crate) fn note_seq_shape(ty: &Ty) -> Option<Shape> {
    match ty {
        Ty::Seq { shape, .. } => Some(shape.clone()),
        _ => None,
    }
}

pub(crate) fn note_seq_item(ty: &Ty) -> Ty {
    match ty {
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); item.clone() },
        _ => Ty::Unknown,
    }
}

pub(crate) fn note_an_integer(name: &str) -> bool { name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64" }

pub(crate) fn note_keeps_the_type(op: &BinaryOp) -> bool { *op == BinaryOp::Add || *op == BinaryOp::Sub || *op == BinaryOp::Mul || *op == BinaryOp::Div || *op == BinaryOp::Rem || *op == BinaryOp::BitAnd || *op == BinaryOp::BitOr || *op == BinaryOp::BitXor }

pub(crate) fn note_width_of(ty: &str) -> u64 {
    match ty {
        "u8" => 8u64,
        "i32" => 32u64,
        "u32" => 32u64,
        _ => 64u64,
    }
}

pub(crate) fn note_a_division(op: &BinaryOp) -> bool { *op == BinaryOp::Div || *op == BinaryOp::Rem }

