pub(crate) fn note_joined(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, segments: &[winnow_grammar::Symbol]) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() {
        let segment = *segment;
        parts.push(world.words.resolve(segment).to_owned());
    }
    parts.join("::")
}

